.svg-wrap { width: 150px; height: 150px; display: flex; align-items: center; justify-content: center; }
.neon-path {
  fill: none; stroke: #ff007f; stroke-width: 4; stroke-linecap: round; stroke-linejoin: round;
  stroke-dasharray: 600; stroke-dashoffset: 600;
  animation: drawNeon 4s ease-in-out infinite alternate;
  filter: drop-shadow(0 0 10px #ff007f) drop-shadow(0 0 20px #ff007f);
}
@keyframes drawNeon { 100% { stroke-dashoffset: 0; } }

